/**
 * Valida una dirección de correo electrónico con reglas adicionales.
 *
 * @param string $email Dirección de correo a validar
 * @return bool True si es válida, False en caso contrario
 */
function validarEmail(string $email): bool {
    // 1. Validar longitud máxima (255 caracteres)
    // Nota: strlen cuenta bytes. Para correos con IDN (dominios internacionales) 
    // se recomienda usar mb_strlen($email, 'UTF-8') > 255
    if (strlen($email) > 255) {
        return false;
    }

    // 2. Validación base con filter_var (cumple RFC 5322)
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return false;
    }

    // 3. Extra: Verificar que el dominio no sea exclusivamente numérico
    $partes = explode('@', $email);
    $dominio = end($partes);

    // preg_match verifica si el dominio contiene ÚNICAMENTE dígitos ASCII del 0 al 9
    if ($dominio !== '' && preg_match('/^[0-9]+$/', $dominio)) {
        return false;
    }

    return true;
}
```

